package com.fitconnect.booking.client; import org.springframework.cloud.openfeign.FeignClient; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.LocalDateTime; @FeignClient(name="class-service") public interface ClassClient {@GetMapping("/api/classes/{id}") ClassSnapshot get(@PathVariable Long id);@PatchMapping("/api/classes/{id}/increment") ClassSnapshot increment(@PathVariable Long id,@RequestParam int spots);@PatchMapping("/api/classes/{id}/decrement") ClassSnapshot decrement(@PathVariable Long id,@RequestParam int spots); record ClassSnapshot(Long id,String name,String instructor,BigDecimal price,LocalDateTime dateTime,Integer currentParticipants,Integer maxParticipants,String status){}
}
